import {useMemo, useState} from 'react'
import {DEFAULT_PAGE_SIZE} from '../types/constants'

interface UsePaginatedDataOptions {
  pageSize?: number
}

interface UsePaginatedDataResult<T> {
  paginatedData: T[]
  currentPage: number
  effectivePage: number
  totalCount: number
  showPagination: boolean
  pageSize: number
  onPageChange: (pageIndex: number) => void
}

export function usePaginatedData<T>(
  data: T[],
  {pageSize = DEFAULT_PAGE_SIZE}: UsePaginatedDataOptions = {},
): UsePaginatedDataResult<T> {
  const [currentPage, setCurrentPage] = useState(0)

  // Clamp currentPage to valid range when data changes (e.g., after filtering)
  const maxPage = Math.max(0, Math.ceil(data.length / pageSize) - 1)
  const effectivePage = Math.min(currentPage, maxPage)

  const paginatedData = useMemo(() => {
    const start = effectivePage * pageSize
    return data.slice(start, start + pageSize)
  }, [data, effectivePage, pageSize])

  return {
    paginatedData,
    currentPage,
    effectivePage,
    totalCount: data.length,
    showPagination: data.length > pageSize,
    pageSize,
    onPageChange: setCurrentPage,
  }
}
