import {Stack} from '@primer/react'
import {useLicenseComplianceData} from '../hooks/use-license-compliance-data'
import {FeatureStatusSection} from './FeatureStatusSection'
import {PRLicenseCheckSection} from './PRLicenseCheckSection'
import {RepositoryPolicySection} from './RepositoryPolicySection'
import type {RepositoryPolicy} from '../types/route'
import styles from '../routes/license-compliance.module.css'

interface LicenseCompliancePageProps {
  licenseComplianceOn: boolean
  repositoryNameWithOwner: string
  repositoryPolicy: RepositoryPolicy
}

export function LicenseCompliancePage({
  licenseComplianceOn,
  repositoryNameWithOwner,
  repositoryPolicy,
}: LicenseCompliancePageProps) {
  const {
    prNumber,
    setPrNumber,
    checkJob,
    error,
    alertsError,
    loading,
    resetMessage,
    fetchLicenseData,
    resetCheckJob,
    openAlerts,
    closedAlerts,
    hasSearched,
  } = useLicenseComplianceData(repositoryNameWithOwner)

  return (
    <div className={styles.container} data-testid="license-compliance-page">
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <h1 className={styles.pageTitle} data-hpc>
        License Compliance
      </h1>

      <Stack direction="vertical" gap="spacious">
        <FeatureStatusSection isEnabled={licenseComplianceOn} />

        <RepositoryPolicySection repositoryPolicy={repositoryPolicy} />

        <PRLicenseCheckSection
          prNumber={prNumber}
          onPrNumberChange={setPrNumber}
          checkJob={checkJob}
          openAlerts={openAlerts}
          closedAlerts={closedAlerts}
          error={error}
          alertsError={alertsError}
          loading={loading}
          resetMessage={resetMessage}
          hasSearched={hasSearched}
          onFetchLicenseData={fetchLicenseData}
          onResetCheckJob={resetCheckJob}
        />
      </Stack>
    </div>
  )
}
